// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { BrowserChrome, DemoStage, DockHeader, MockPage, type Build } from '@/app/demos/stage'

import { CAPTIONS, EMPTY, HOPS } from './script'

const build: Build = ({ tl, q, qa, pos, step, final, move, click, type, wait, cursorOut }) => {
  const centre = (index: number) => {
    const point = pos(`node-${index}`)
    return { x: point.x - 5, y: point.y - 5 }
  }

  step(0)
  move('url', { ax: 0.3, at: 0.2 })
  click('url')
  type('url-text', HOPS[0].url, { speed: 0.03 })
  tl.fromTo(q('spinner'), { opacity: 0 }, { opacity: 1, duration: 0.2 })
  tl.to(q('spinner'), { rotation: 720, duration: 2.4, ease: 'none' }, '<')

  step(1, '-=1.6')
  HOPS.forEach((hop, index) => {
    if (index > 0) {
      const from = centre(index - 1)
      const to = centre(index)
      tl.fromTo(
        q('traveler'),
        { x: from.x, y: from.y },
        {
          motionPath: {
            path: [from, { x: from.x + 10, y: (from.y + to.y) / 2 }, to],
            curviness: 1.2,
          },
          duration: 0.6,
          ease: 'power2.inOut',
        },
        '+=0.35',
      )
      tl.to(
        q('url-text'),
        { text: { value: hop.url, delimiter: '' }, duration: 0.3, ease: 'none' },
        '<0.1',
      )
    }
    tl.fromTo(
      q(`hop-${index}`),
      { opacity: 0, x: 12 },
      { opacity: 1, x: 0, duration: 0.3, ease: 'power3.out' },
      index === 0 ? 'step-1' : '>-0.15',
    )
    tl.fromTo(
      q(`node-${index}`),
      { scale: 0 },
      { scale: 1, duration: 0.3, ease: 'back.out(3)' },
      '<',
    )
    if (index === 0)
      tl.fromTo(q('traveler'), { opacity: 0, ...centre(0) }, { opacity: 1, duration: 0.2 }, '<0.1')
    if (index > 0)
      tl.fromTo(q(`line-${index - 1}`), { scaleY: 0 }, { scaleY: 1, duration: 0.3 }, '<')
  })
  tl.to(q('spinner'), { opacity: 0, duration: 0.2 })
  tl.to(q('blank'), { opacity: 0, duration: 0.4 }, '<')

  step(2, '+=0.3')
  const last = HOPS.length - 1
  tl.to(q(`hop-${last}`), {
    borderColor: 'rgba(52,211,153,0.7)',
    backgroundColor: 'rgba(52,211,153,0.08)',
    duration: 0.3,
  })
  tl.to(q(`node-${last}`), { backgroundColor: '#34d399', duration: 0.3 }, '<')
  tl.fromTo(
    q('final'),
    { opacity: 0, scale: 0.6 },
    { opacity: 1, scale: 1, duration: 0.3, ease: 'back.out(3)' },
    '<',
  )
  tl.to(q('traveler'), { scale: 2.2, opacity: 0, duration: 0.5, ease: 'power2.out' }, '<')

  step(3, '+=0.6')
  move('clear')
  click('clear')
  tl.to([...qa('hop'), ...qa('node'), ...qa('line')], { opacity: 0, duration: 0.25 }, '<')
  tl.fromTo(q('empty'), { opacity: 0 }, { opacity: 1, duration: 0.3 }, '>-0.05')
  cursorOut('+=0.3')
  final()
  wait(1.2)
}

export default function Demo() {
  return (
    <DemoStage
      label="Redirect Tracer recording each URL a short link passes through until the final page"
      steps={CAPTIONS}
      build={build}
    >
      <BrowserChrome
        url=""
        tab="Spring sale"
        panelWidth={250}
        panel={
          <div className="flex h-full flex-col">
            <DockHeader />
            <div className="relative flex min-h-0 flex-1 flex-col gap-2 p-2.5">
              <div className="flex gap-1.5">
                <span className="rounded-md border border-line-strong px-2 py-1 text-[9.5px] text-ink-soft">
                  Try again
                </span>
                <span data-d="clear" className="rounded-md px-2 py-1 text-[9.5px] text-muted">
                  Clear
                </span>
              </div>
              <ol className="relative space-y-3">
                {HOPS.map((hop, index) => (
                  <li key={hop.url} className="relative flex gap-2.5">
                    <span className="relative flex w-3 shrink-0 justify-center pt-2.5">
                      <span
                        data-d={`node node-${index}`}
                        className="relative z-10 size-2.5 rounded-full bg-[var(--accent)]"
                      />
                      {index < HOPS.length - 1 ? (
                        <span
                          data-d={`line line-${index}`}
                          className="absolute left-1/2 top-5 h-[calc(100%+4px)] w-px origin-top bg-[var(--accent)]/40"
                        />
                      ) : null}
                    </span>
                    <div
                      data-d={`hop hop-${index}`}
                      className="min-w-0 flex-1 rounded-md border border-line bg-white/[0.03] px-2 py-1.5 opacity-0"
                    >
                      <p className="flex items-center gap-1.5 text-[9px] text-muted">
                        #{index + 1}
                        {index === HOPS.length - 1 ? (
                          <span
                            data-d="final"
                            className="rounded bg-emerald/15 px-1 text-[8px] font-medium text-emerald opacity-0"
                          >
                            Final
                          </span>
                        ) : null}
                      </p>
                      <p className="mt-0.5 break-all font-mono text-[9.5px] leading-snug text-ink">
                        {hop.url}
                      </p>
                    </div>
                  </li>
                ))}
              </ol>
              <p
                data-d="empty"
                className="absolute inset-x-2.5 top-12 text-[10px] text-muted opacity-0"
              >
                {EMPTY}
              </p>
            </div>
          </div>
        }
      >
        <MockPage variant="landing" title="The spring sale is on" />
        <div data-d="blank" className="absolute inset-0 flex items-center justify-center bg-white">
          <span
            data-d="spinner"
            className="size-6 rounded-full border-2 border-black/10 border-t-[#7c3aed] opacity-0"
          />
        </div>
      </BrowserChrome>
      <span
        data-d="traveler"
        className="absolute left-0 top-0 z-30 size-2.5 rounded-full bg-white opacity-0 shadow-[0_0_14px_4px_var(--accent)]"
      />
    </DemoStage>
  )
}
